Thanks for this.
Looking into it. | Here's my repro of the Proxy with a call, followed by the delegate call:

```
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

import {Test, console} from "forge-std/Test.sol";

contract MockContract {
    function initialize(address initializationAddress) public pure {}
}

contract Proxy {
    function upgradeToAndCall(
        address newImplementation,
        bytes memory data
    ) external {
        address(newImplementation).delegatecall(data);
    }
}

contract ProxyController {
    Proxy immutable PROXY;

    constructor(address proxy) {
        PROXY = Proxy(proxy);
    }

    function proxy_upgradeAndCall(
        address newImplementation,
        bytes calldata data
    ) external {
        PROXY.upgradeToAndCall(newImplementation, data);
    }
}

contract ExpectCallTest is Test {
    function testProxyCallDelegateCall() public {
        address implementation = address(new MockContract());
        Proxy proxy = new Proxy();
        ProxyController proxyController = new ProxyController(
            address(proxy)
        );

        bytes memory data = abi.encodeCall(
            MockContract.initialize,
            (address(0xdeadbeef))
        );

        vm.expectCall(
            address(proxy),
            abi.encodeCall(proxy.upgradeToAndCall, (implementation, data))
        );
        vm.expectCall(address(implementation), data);

        proxyController.proxy_upgradeAndCall(implementation, data);
    }
}
```

Maybe it's the same thing, but just in case adding it here to reflect my exact case | I would like to add here another repro case, that uses a library and a proxy:

```
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

import {Test, console} from "forge-std/Test.sol";

library LibraryContract {
    function getContentURI(
        uint256 profileId,
        uint256 pubId
    ) external view returns (string memory) {
        return "";
    }
}

contract MainContract {
    function getContentURI(
        uint256 profileId,
        uint256 pubId
    ) external view returns (string memory) {
        return LibraryContract.getContentURI(1, 2);
    }
}

contract Proxy {
    MainContract immutable IMPLEMENTATION;

    constructor(address implementation) {
        IMPLEMENTATION = MainContract(implementation);
    }

    function getContentURI(uint256 profileId, uint256 pubId) external {
        address(IMPLEMENTATION).delegatecall(
            abi.encodeWithSignature(
                "getContentURI(uint256,uint256)",
                profileId,
                pubId
            )
        );
    }
}

contract CollectNFTTest is Test {
    function testTokenURI() public {
        MainContract mainContractImpl = new MainContract();
        Proxy proxy = new Proxy(address(mainContractImpl));

        vm.expectCall(
            address(proxy),
            abi.encodeCall(MainContract.getContentURI, (1, 2)),
            1
        );
        proxy.getContentURI(1, 2);
    }
}
```

It says the call was called 3 times. And I'm not sure if this is correct (it was counted as 1 time before that commit)

cc @mattsse

issue_body:
**Bug Description**
Hello,
Many of my users using Ledger have this kind of error when they interact with smart contract:
`The method eth_sendTransaction does not exist/is not available`
Has anyone ever had this kind of trouble before?
I specify that with the other connectors it works.
I use Infura as RPC provider.

**Reproduction**
```
// Helper to make write request to smart contract
// and dispatch success(after 1 confirmation) or error
export const sendContract = function* (action, method, methodParams, callParams) {
  try {
    const receiptResult = yield new Promise((res, rej) => {
      action.data.contract.methods[method](...methodParams).send(...callParams)
        .on('confirmation', (confirmationNumber, receipt) => {
          if (confirmationNumber) res({ confirmationNumber, receipt });
        }).on('error', rej);
    });
    yield put({ data: receiptResult, type: onSuccess(action.type) });
  } catch (error) {
    yield put({ data: error, type: onError(action.type) });
  }
};
```
https://github.com/vanmoortel/lrc-staking-dapp/blob/master/src/utils/simpleContractFetching.js
